use settlement_gate::*;
fn reference(balance: u64, amount: u64, fee: u64) -> Option<u128> {
    let mut b=[0u128;4]; let mut d=[0u128;4];
    for i in 0..4 { b[i]=(((fee>>(16*i))&0xFFFF) as u128)+1; let a=((amount>>(16*i))&0xFFFF) as u128; d[i]=a.min(b[i]-1); }
    let o2=b[3]; let o1=b[2]*o2; let o0=b[1]*o1;
    let idx=d[0]*o0+d[1]*o1+d[2]*o2+d[3];
    let t=(amount as u128)/2+idx/2;
    if t <= balance as u128 { Some(t) } else { None }
}
#[test]
fn fuzz() {
    let mut s: u64 = 0x9E3779B97F4A7C15;
