        let a=pick(1); let f=pick(3);
        let t = reference(u64::MAX,a,f).unwrap();
        let bal = match i%3 { 0 => next(), 1 => t as u64, _ => (t as u64).wrapping_sub(1) };
        let r = reference(bal,a,f);
        let got = authorize(bal,a,f).map(|x| x.total_debit as u128);
        assert_eq!(got, r, "bal={} a={} f={}", bal, a, f);
    }
}
